{
  "name": "可调谐飞秒激光器",
  "name_en": "Tunable femtosecond laser",
  "manufacturer": "Coherent",
  "description": "这是一类可调谐输出波长的超快飞秒激光器，通常带有快门、对准模式以及色散补偿相关设置（如 GDD）。它常用于双光子显微、非线性光学实验、超快光谱和需要可调近红外激发光源的科研场景。",
  "description_en": "This is a tunable ultrafast femtosecond laser with adjustable output wavelength, typically including a shutter, alignment mode, and dispersion-compensation controls such as GDD. It is commonly used in two-photon microscopy, nonlinear optics, ultrafast spectroscopy, and other research applications requiring a tunable near-infrared excitation source.",
  "tag_hints": [
    "tunable femtosecond laser",
    "ultrafast optics",
    "two-photon microscopy",
    "wavelength tuning",
    "GDD compensation",
    "laser shutter control",
    "alignment mode"
  ],
  "actions": [
    {
      "action_name": "auto-getPower",
      "description": "获取激光输出功率",
      "description_en": "Get the laser output power"
    },
    {
      "action_name": "auto-getWavelength",
      "description": "获取输出波长",
      "description_en": "Get the output wavelength"
    },
    {
      "action_name": "auto-setWavelength",
      "description": "设置输出波长",
      "description_en": "Set the output wavelength"
    },
    {
      "action_name": "auto-getWavelengthRange",
      "description": "获取可调波长范围",
      "description_en": "Get the tunable wavelength range"
    },
    {
      "action_name": "auto-getGDDMinMax",
      "description": "获取当前波长下 GDD 的最小值和最大值",
      "description_en": "Get the minimum and maximum GDD values at the current wavelength"
    },
    {
      "action_name": "auto-getGDD",
      "description": "获取当前 GDD 设置",
      "description_en": "Get the current GDD setting"
    },
    {
      "action_name": "auto-getComp",
      "description": "获取色散补偿设置",
      "description_en": "Get the dispersion compensation setting"
    },
    {
      "action_name": "auto-setGDD",
      "description": "设置 GDD 值",
      "description_en": "Set the GDD value"
    },
    {
      "action_name": "auto-clearGDD",
      "description": "清除 GDD 补偿设置",
      "description_en": "Clear the GDD compensation setting"
    },
    {
      "action_name": "auto-isTuning",
      "description": "获取是否正在调谐波长",
      "description_en": "Get whether wavelength tuning is in progress"
    },
    {
      "action_name": "auto-getShutter",
      "description": "获取快门状态",
      "description_en": "Get the shutter state"
    },
    {
      "action_name": "auto-setShutter",
      "description": "设置快门开关状态",
      "description_en": "Set the shutter open/closed state"
    },
    {
      "action_name": "auto-setAlignment",
      "description": "设置对准模式",
      "description_en": "Set the alignment mode"
    },
    {
      "action_name": "auto-getAlignment",
      "description": "获取对准模式状态",
      "description_en": "Get the alignment mode state"
    },
    {
      "action_name": "auto-clearBuffer",
      "description": "清空设备通信缓冲区",
      "description_en": "Clear the device communication buffer"
    },
    {
      "action_name": "auto-read",
      "description": "读取设备返回数据",
      "description_en": "Read data returned by the device"
    },
    {
      "action_name": "auto-write",
      "description": "向设备发送原始命令数据",
      "description_en": "Write raw command data to the device"
    },
    {
      "action_name": "auto-close",
      "description": "关闭与设备的通信连接",
      "description_en": "Close the communication connection to the device"
    },
    {
      "action_name": "auto-readPacket",
      "description": "读取设备返回的数据包",
      "description_en": "Read a packet returned by the device"
    }
  ]
}

